contract InvMutTest {
    C c;
    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(address to, uint256 value) public {
        require(to == address(0));
        uint256 beforeBal = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        bool reverted;
        c.transfer(to, value); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        assert(reverted && c.balanceOf(address(this)) == beforeBal);
    }
}

