pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ERCDDAToken c;

    function setUp() public {
        c = new ERCDDAToken(0, "", "");
    }

    function _run(address to, uint256 value) internal {
        to = address(0);
        uint256 beforeBal;
        try c.balanceOf(address(this)) returns (uint256 __r) { beforeBal = __r; } catch { return; }
        bool reverted;
        try c.transfer(to, value) { reverted = false; } catch { reverted = true; }
        assertTrue(reverted && c.balanceOf(address(this)) == beforeBal);
    }

    function testFuzz_run(address to, uint256 value) public {
        _run(to, value);
    }

    receive() external payable {}
}
